    "<b>威力是攻击力的百分比</b>：卡面写「威力 110」就是打出 1.1 倍攻击。费用买的就是这个倍率 —— 1 费约 95~140%、2 费约 200~260%、3 费约 310~420%、4 费约 430~560%。<b>每点 AP 买到的威力随费用上升</b>，所以把 AP 花在贵牌上永远比连打 0 费牌划算（0 费牌只有 25~45%，它卖的是附加效果和「不花 AP」）。": "<b>威力は攻撃力のパーセント</b>：カードに「威力 110」とあれば攻撃の 1.1 倍を叩き込む。コストで買っているのはこの倍率だ —— 1 コストで約 95~140%、2 コストで約 200~260%、3 コストで約 310~420%、4 コストで約 430~560%。<b>1 AP あたりで買える威力はコストが高いほど増える</b>ので、AP は高いカードに使うほうが 0 コストを連打するより常に得（0 コストは 25~45% しかなく、売り物は追加効果と「AP を使わない」こと）。",
    "<code>1</code> ~ <code>9</code> 打出手牌中第 N 张。": "<code>1</code> ~ <code>9</code> で手札の N 枚目を出す。",
