    "· 行动点 AP = {base} + 敏捷÷{per}（上限 {max}）→ 你现在 **{now} 点**\n": "· 行動点 AP = {base} + 敏捷÷{per}（上限 {max}）→ 現在 **{now} 点**\n",
    "……什么也没发生。": "……何も起こらなかった。",
    "……喝一口试试？": "……一口飲んでみる？",
