    "底下是一堆蛋壳，壳里塞着别人藏起来的药，居然还没坏。\n「谁藏的？我先借走咯。」\n获得{item} ×1。": "下にあったのは卵の殻の山で、殻の中には誰かが隠した薬が詰まっていた。まだ傷んでいない。\n「誰が隠したの？　先に借りていくね。」\n{item} ×1 を手に入れた。",
