    "想换牌：营地的<code>冥想</code>能把一张牌换成随机的高稀有度牌（只能二选一，不能又休息又冥想）。": "カードを入れ替えたいなら：オアシスの<code>めいそう</code>で、1 枚をランダムな高レアリティのカードに変えられる（どちらか一方だけ。休憩とめいそうの両方は選べない）。",
    "想换牌：营地的「冥想」可以把一张牌换成随机的高稀有度牌。": "入れ替えたいなら：オアシスの「めいそう」で、カード 1 枚をランダムな高レアリティのカードに替えられる。",
    "想精简：去商店买「卡牌移除服务」删掉不要的牌，同一家店里越删越贵。": "絞りたいなら：ショップで「カード削除サービス」を買って要らないカードを消す。同じ店では消すほど値上がりする。",
    "想让卡组更精：去商店买<code>卡牌移除服务</code>删掉不要的牌，同一家店里越删越贵（最多删到剩 3 张）。": "デッキを絞りたいなら：ショップで<code>カード除去サービス</code>を買って不要なカードを削除する。同じ店では削除のたびに値段が上がる（デッキは 3 枚まで減らせる）。",
