    "把它搬开看看下面。": "どけて下を見てみる。",
    "把对手的属性堆上去。": "相手の能力を積み上げる。",
    "把对手身上的中毒 / 剧毒 / 灼伤层数立刻爆成伤害（每层约 {per} 倍中毒伤害）并清空。": "相手のどく / もうどく / やけどの層を、いますぐダメージとして爆発させ（1 層あたりどくダメージの約 {per} 倍）、そのあと全部消える。",
    "把手伸进去捞（50% 获得卡 / 50% -20 HP）": "手を突っ込んで掬い出す（50% カードを獲得 / 50% -20 HP）",
