    "把碎卡埋起来（幸运 +3）": "砕けたカードを埋める（幸運 +3）",
    "把碎片埋起来吧。": "砕けたカードを埋めてやろう。",
    "把窝往里推半米。": "巣を奥へ 50 センチ押し込む。",
    "把窝往里推半米（最大生命 +14）": "巣を奥へ 50 センチ押し込む（最大HP +14）",
    "抓挠": "ひっかく",
    "护盾": "シールド",
    "护盾 {n}：先替你吃伤害，吃光之后剩下的才掉血。\n持有者自己的回合开始时清空，所以它是「撑过这一轮」的资源。": "シールド {n}：まず身代わりにダメージを受けてくれて、それが尽きてから残りがHPに来る。\n持ち主のターン開始時に消えるので、「この一巡を耐え切る」ための資源だ。",
    "护盾 {shield} ｜ 回复 {heal} ｜ 状态 {status} ｜ 强化 {buff}": "シールド {shield} ｜ 回復 {heal} ｜ 状態 {status} ｜ 強化 {buff}",
    "护盾在持有者自己的回合开始时清空，所以它其实是「这一轮的减伤」。": "シールドは持ち主自身のターン開始時に消える。つまり実質は「この 1 ターンだけのダメージ軽減」だ。",
    "护盾类卡牌（变硬、铁壁、守住）的量会随你的防御成长。": "シールド系のカード（かたくなる、てっぺき、まもる）が張る量は、自分の防御とともに伸びていく。",
    "护盾量随**防御**成长：实际护盾 = 卡面基数 × (1 + 防御 ÷ {div})。\n所以基数越大的护盾牌，吃到的防御加成也越多。": "シールド量は**防御**に応じて伸びる：実際のシールド = カードの基本値 × (1 + 防御 ÷ {div})。\nつまり基本値が大きいシールドカードほど、防御の恩恵を多く受けられる。",
    "护盾：先于 HP 承受伤害，回合开始时清空（「广域防守」给的那一份不会清）。": "シールド：HP より先にダメージを受ける。自分のターン開始時に消える（「ワイドガード」で得た分は消えない）。",
    "护盾：先于 HP 承受伤害，持有者自己的回合开始时清空——所以它是「撑过这一轮」的资源。": "シールド：HP より先にダメージを受ける。持ち主の自分のターン開始時に消える——つまり「この一巡を耐えきる」ためのリソースだ。",
    "护符 / 活力药这类「本局 +N」的道具，<b>拿到手就自动生效</b>了，不会留在背包里。": "護符 / かつりょくのくすりなど「本局 +N」のアイテムは、<b>入手した瞬間に自動で発動</b>し、バッグには残らない。",
    "护符与活力药这类「本局 +N」的道具，<b>拿到手就自动生效</b>，不会留在背包里。": "護符やかつりょくのくすりのような「本局 +N」のアイテムは、<b>手に入れた瞬間に自動で効果を発揮</b>し、バッグには残らない。",
    "护符匠": "護符職人",
    "抵抗{status}": "抵抗{status}",
    "抵达步数": "到達歩数",
    "抽 2 张。": "2 枚ドロー。",
    "抽 2 张，回复 1 点 AP。": "2 枚ドローし、AP を 1 回復。",
    "抽 2 张，本回合多出 1 次出牌机会。": "2 枚ドロー。このターン、出せる枚数が 1 増える。",
    "抽 3 张，本回合多出 2 次出牌机会。": "3 枚ドロー。このターン、出せる枚数が 2 増える。",
    "抽上来的牌比手牌上限（{base} + 敏捷 ÷ {per}，上限 {max}）多时，<b>只抽到手牌满为止</b>，剩下的留在牌堆顶 —— 不会凭空丢掉。": "引いた枚数が手札の上限（{base} + 敏捷 ÷ {per}、上限 {max}）を超えるときは、<b>手札が埋まるまでしか引かない</b>。残りは山札の一番上に残る —— 消えたりはしない。",
    "抽牌": "ドロー",
    "抽牌 = {base} + 敏捷 ÷ {perAgi}（向下取整，最高 {max}）": "ドロー = {base} + 敏捷 ÷ {perAgi}（切り捨て、最高 {max}）",
    "抽牌 {draw} 张 —— 手牌上限 {hand} 张，抽到手牌满为止（放不下的留在牌堆顶，不会消失）。": "ドロー {draw} 枚 —— 手札上限は {hand} 枚で、手札が埋まるまで引く（入りきらない分は山の上に残る、消えたりはしない）。",
    "抽牌 {draw} ｜ 回 AP {ap} ｜ 净化 {cleanse}": "ドロー {draw} ｜ AP 回復 {ap} ｜ 浄化 {cleanse}",
    "抽牌与行动点": "ドローと行動点",
    "抽牌：从卡组顶抽到手牌。\n打出去的牌会进**弃牌区**，牌堆抽空、还要再抽的时候，弃牌区才会洗回牌堆。所以牌组薄的时候，同一张牌一轮里能被打上好几次 —— 但每回合的出牌次数是有限的。": "ドロー：山札の上から手札に引く。\n使ったカードは**捨て札置き場**へ。山札が尽きて、さらに引く必要が出たときに初めて捨て札置き場が山札へ戻る。だから山札が薄いと、同じカードが一巡で何度も使える —— ただし 1 ターンに出せる枚数には限りがある。",
    "抽牌：从牌堆再抽一张。": "ドロー：山札からもう 1 枚引く。",
    "拆一块船板带走。": "船板を一枚外して持ち帰る。",
    "拆一块船板带走（防御 +3）": "船板を一枚外して持ち帰る（防御 +3）",
    "拍落": "はたきおとす",
    "拒绝（-12 HP，攻击 +2）": "断る（-12 HP、攻撃 +2）",
    "拜一下就走": "手を合わせてから立ち去る",
