    "虚弱": "じゃくたい",
    "虚弱：攻击力降低 25%。挂上之后那一方要打完整整一个回合才掉 1 层，所以「1 层」= 削弱对方一个回合。": "弱体：攻撃力が 25% 下がる。付いた側が丸々 1 ターン動ききって、ようやく 1 層減る —— つまり「1 層」= 相手を 1 ターン弱らせるということ。",
    "虫": "むし",
