    "螺钉地鼠": "モグリュー",
    "血祭": "ちのいけにえ",
    "行动点": "行動点",
    "行动点 = {base} + 敏捷 ÷ {perAgi}（上限 {max}）": "行動点 = {base} + 敏捷 ÷ {perAgi}（上限 {max}）",
    "行动点 AP {ap} 点 —— 回合开始回满，出牌花的就是它。": "行動点 AP {ap} 点 —— ターン開始で満タンに戻り、カードを出すたびにここから払う。",
    "行动点 {ap}/{max}：打出卡牌要花行动点。\n回合开始时回满，敏捷越高每回合越多。": "行動点 {ap}/{max}：カードを出すには行動点を使う。\nターン開始時に全回復し、敏捷が高いほど毎ターン増える。",
    "行动点费用：打出这张牌要花 {ap} 点行动点。": "行動点コスト：このカードを出すには行動点を {ap} 点消費する。",
    "行动点（AP）：每回合回满，数量 = {base} + 敏捷 ÷ {per}（上限 {max}）。打出卡牌要花 AP。": "行動点（AP）：毎ターン満タンまで回復し、数は {base} + 敏捷 ÷ {per}（上限 {max}）。カードを出すには AP を使う。",
    "装一瓶带走。": "瓶に詰めて持ち帰る。",
    "装一瓶带走（获得活力药 ×1）": "瓶に詰めて持ち帰る（かつりょくのくすり ×1 を獲得）",
    "装不认识。": "知らないふりを決め込む。",
    "装的时候瓶子外壁结了一层白霜，你舔了一下，舌头麻了半天。\n「唔！麻了麻了 —— 这个真的能喝吗？」\n获得{item} ×1。": "詰めていると瓶の外側に白い霜が降りた。舐めてみたら、舌がしばらく痺れた。\n「ん！痺れた痺れた —— これ、本当に飲めるの？」\nアイテム「{item}」を 1 個獲得。",
    "要（获得 1 张稀有卡，-12 HP）": "もらう（レアカード 1 枚獲得、-12 HP）",
    "解法：「白雾」「焕然一新」这类解状态牌可以直接清掉。": "解法：「しろいきり」「リフレッシュ」のような状態解除カードなら直接消せる。",
    "让对手攻击 -35%。": "相手の攻撃 -35%。",
    "让对手敏捷 -35%。": "相手の敏捷-35%。",
    "让对手防御 -1。": "相手の防御 -1。",
    "让对手防御 -35%。抽 1 张。": "相手の防御-35%。1枚ドロー。",
    "让对手防御 -3，抽 1 张。": "相手の防御 -3。ドロー 1 枚。",
    "设置": "設定",
    "诅咒棺": "カースミイラ",
    "话匣子一开就收不住。": "話し始めたら止まらない。",
    "语言 / Language / 言語": "言語 / Language",
    "语言已切换：{name}": "言語を切り替えた：{name}",
    "说一声「借」就好啦。": "「借ります」って言えばいいんだよ。",
    "说不定主人只是去打水了。": "持ち主は水でも汲みに行っただけかもしれない。",
    "说你不认识它": "知らないふりをする",
    "说明": "説明",
    "诶，里面有东西在动。": "えっ、中で何か動いてる。",
    "读取失败：文件不是本作的存档。": "読み込みに失敗：このゲームのセーブデータではない。",
    "读心": "こころのめ",
    "豪力": "ゴーリキー",
    "贝壳缝里伸出一条舌头，很快又缩回去。": "貝の隙間から舌が一本伸びて、すぐに引っ込んだ。",
    "贝壳里侧刻着一串很细的痕，像谁记下来的招式。你看懂了。\n「哟，这是谁写的呀？我收下咯。」\n获得「{card}」。": "貝の内側には細い傷跡が連なっていて、誰かが書き残した技のようだった。意味が分かった。\n「へえ、これ誰が書いたのかな？もらってくね。」\n「{card}」を獲得。",
    "购买": "購入",
    "费用": "費用",
    "费用买的是威力：**威力是攻击力的百分比**（威力 110 = 打出 1.1 倍攻击）。\n每点 AP 买到的威力随费用上升，所以「把 AP 花在贵牌上」永远比连打 0 费牌划算。": "コストで買うのは威力：**威力は攻撃力の割合**（威力 110 = 攻撃力の 1.1 倍を叩き出す）。\n1 AP あたりに買える威力はコストが上がるほど増える。だから「AP は高いカードに使う」ほうが、0 コストを連打するより常に得だ。",
    "赋予状态（持续掉血）": "状態異常を与える（継続ダメージ）",
    "赤岩峡谷": "赤岩の峡谷",
    "赫拉克罗斯": "ヘラクロス",
    "走到首领节点前会先自动回复 {pct}% 生命。": "ボスのノードへ向かう前に、まず HP を {pct}% 自動回復する。",
    "走到首领节点时会先自动恢复 {pct} 生命。": "ボスにたどり着くと、まず最大HPの {pct} が自動回復する。",
    "走廊尽头堆着别人的旧东西，其中一张卡还完好无损。\n「这个我收下啦。」\n获得「{card}」。": "通路の突き当たりには誰かの古い荷物が積んであって、その中の一枚のカードはまだ無傷だった。\n「これはもらっておくね。」\n「{card}」を手に入れた。",
    "走路草": "ナゾノクサ",
    "走近了才看出，那盏灯在飘，而且它在等你走近。": "近づいてようやく分かる。あの灯りは浮いていて、しかもこちらが近づくのを待っている。",
    "趁它们停的时候听（获得 1 张卡）": "止まった隙に耳を澄ます（カード 1 枚獲得）",
    "趁安静的时候听。": "静かなうちに耳を澄ます。",
    "趁着亮整理卡组。": "明るいうちにデッキを整理する。",
    "超级角击": "メガホーン",
    "超能力": "エスパー",
    "超频": "オーバークロック",
    "趴在光里晒一会儿。": "光の中に寝そべって浴びる。",
    "趴在光里晒一会儿（回复 40 HP）": "光の中に寝そべってしばらく浴びる（40 HP 回復）",
    "跑腿商人": "飛脚商人",
    "跟它讨价还价（-12 HP，幸运 +2）": "値切ってみる（HP -12、幸運 +2）",
    "跟它讲讲价。": "ちょっと値切ってみる。",
    "跟着叫一声！": "一緒に一声鳴く！",
