    "里面是几瓶还算完好的药和一个钱袋。\n「今天运气不错。」\n金币 +{gold}，获得{item} ×1。": "Inside are a few bottles of medicine still in decent shape, and a pouch of coins.\n\"Good luck today.\"\ngold +{gold}, got {item} ×1.",
    "里面有半袋钱和一瓶还没开封的药。你按原样把钱袋口系了回去，然后又解开。\n「我先借用一下。下次见到你再还。」\n金币 +{gold}，获得{item} ×1。": "Inside there's half a bag of coin and a bottle of medicine, still sealed. You tie the pouch back up exactly as it was — then untie it again.\n\"I'll just borrow this for now. I'll give it back next time I see you.\"\ngold +{gold}, gained {item} x1.",
